function formatted(item,places=1,{money=false,ratio=false,percent=false}={}) {
  const value=restoreQuantity(item);
  if(!value) return '—';
  let number=decimalText(value,places),[whole,fraction='']=number.split('.');
  whole=whole.replace(/\B(?=(\d{3})+(?!\d))/g,',');
