    const blocks = before.blocks * 512n;
    if (!before.isFile() || before.size !== 0n || fd < 0)
      throw new BuyerResponseFileError('RESPONSE_FILE_ALLOCATION_IDENTITY');
    checkPreparation();
    await reserveFile({fileHandle:handle, path, kind, bytes:amount, signal:preparationSignal});
    checkPreparation();
    const after = await handle.stat({bigint:true}), named = await lstat(path,{bigint:true});
    if (handle.fd !== fd || after.dev !== before.dev || after.ino !== before.ino ||
        !named.isFile() || named.dev !== after.dev || named.ino !== after.ino ||
        after.nlink !== before.nlink || after.size !== before.size || after.mode !== before.mode ||
        after.blocks * 512n < BigInt(amount))
      throw new BuyerResponseFileError('RESPONSE_FILE_ALLOCATION_IDENTITY');
    return Object.freeze({kind, reservedBytes:amount, device:String(after.dev), inode:String(after.ino),
      allocatedBytes:String(after.blocks * 512n), previousAllocatedBytes:String(blocks),
      logicalSizePreserved:true});
  }

  async function cleanup({ keepPartial = false } = {}) {
    const warnings = [];
    for (const [handle, path] of [[file, partialPath], [reservation, reservationPath]]) {
      if (handle) {
        // KEEP_SIZE leaves any unused allocation beyond EOF. Release that tail
        // on the same inode, preserving every byte actually written, including
        // a retained incomplete response after cancellation or a read failure.
        if (reserveFile !== undefined) {
          try { const current = await handle.stat(); await handle.truncate(current.size); await handle.sync(); }
          catch (error) { warnings.push({path, code:error.code ?? 'ALLOCATION_RELEASE_FAILED'}); }
        }
        try { await handle.close(); }
        catch (error) { warnings.push({ path, code: error.code ?? 'CLOSE_FAILED' }); }
      }
    }
    file = null; reservation = null;
    for (const path of [probePath, !keepPartial && partialPath, reservationPath]) {
      if (!path) continue;
      try { await unlink(path); }
      catch (error) { if (error.code !== 'ENOENT') warnings.push({ path, code: error.code ?? 'UNLINK_FAILED' }); }
    }
    return warnings;
  }

  try {
    const parent = await realpath(dirname(resolve(destination)));
    finalPath = join(parent, basename(destination));
    await absent(finalPath);
    // A filename-derived reservation follows the parent filesystem's own
    // case comparison, unlike a hash which gives case aliases different locks.
    const lockPath = join(parent, `.${basename(finalPath)}.x402-download.lock`);
    try { reservation = await open(lockPath, 'wx', 0o600); }
    catch (cause) {
      throw new BuyerResponseFileError(cause.code === 'EEXIST' ? 'RESPONSE_FILE_RESERVED' : 'RESPONSE_FILE_PREPARE_FAILED', finalPath, { cause });
    }
    // Record only paths actually created by this instance: never unlink another
    // process's existing lock or a coincidentally named partial file.
    reservationPath = lockPath;
    const candidate = join(parent, `.x402-response-${randomUUID()}.partial`);
    file = await open(candidate, 'wx', 0o600);
    partialPath = candidate;
    const reservationBytes = Buffer.from(JSON.stringify({ destination: finalPath, partialPath, pid: process.pid,
      ...(reservationTag === undefined ? {} : { reservationTag }) }) + '\n');
    if (reserveFile !== undefined) {
      const response = await reserve(file, partialPath, 'buyer-response', maxBytes);
      const lock = await reserve(reservation, reservationPath, 'buyer-response-reservation', reservationBytes.length);
      allocation = Object.freeze({mode:'HELD_DESTINATION_DESCRIPTORS', response, reservation:lock});
    }
    await reservation.writeFile(reservationBytes);
    await reservation.sync();
    // Discover unsupported hard links before the caller sends a paid request.
    const probe = join(parent, `.x402-link-${randomUUID()}`);
    await link(partialPath, probe);
    probePath = probe;
    await unlink(probePath);
    probePath = null;
    await absent(finalPath);
    checkPreparation();
    state = 'PREPARED';
  } catch (cause) {
    const cleanupWarnings = await cleanup();
    const error = cause instanceof BuyerResponseFileError ? cause : new BuyerResponseFileError('RESPONSE_FILE_PREPARE_FAILED', '', { cause });
    error.cleanupWarnings = cleanupWarnings;
    throw error;
  }

  async function saveOnce(result, signal, onRecord, byteSource = false) {
    let reader = null, timer = null, onExternalAbort = null, complete = false;
    const parser = streamOptions ? createResponseStreamParser(streamOptions) : null;
    const hash = createHash('sha256');
    let digest = null;
    const stop = () => { throw controller.signal.reason; };
    const check = () => { if (controller.signal.aborted) stop(); };
    const emitRecords = async records => {
      if (!onRecord) return;
      for (const record of records) {
        check();
        try {
          // Honor the same deadline even if a consumer never resolves.
          await readChunk({ read: () => Promise.resolve().then(() => onRecord(record)) }, controller.signal);
        } catch (cause) {
          check();
          throw new BuyerResponseFileError('RESPONSE_STREAM_CONSUMER_FAILED', '', { cause });
        }
      }
    };
    try {
      if (signal !== undefined && !(signal instanceof AbortSignal))
        throw new BuyerResponseFileError('BAD_RESPONSE_FILE_SIGNAL');
      if (onRecord !== undefined && (typeof onRecord !== 'function' || !parser))
        throw new BuyerResponseFileError('BAD_RESPONSE_STREAM_CONSUMER');
      if (signal) {
        onExternalAbort = () => controller.abort(new BuyerResponseFileError('RESPONSE_FILE_ABORTED'));
        signal.addEventListener('abort', onExternalAbort, { once: true });
        if (signal.aborted) onExternalAbort();
      }
      timer = setTimeout(() => controller.abort(new BuyerResponseFileError('RESPONSE_FILE_TIMEOUT')), timeoutMs);
      check();
      let body, contentType, objectMetadata = {};
      if (byteSource) {
        if (!(result.bytes instanceof Uint8Array) || result.bytes.byteLength > maxBytes)
          throw new BuyerResponseFileError('RESPONSE_FILE_BYTE_SOURCE_INVALID');
        if (typeof result.contentType !== 'string' || result.contentType.length > 256 ||
            /[\x00-\x1f\x7f]/.test(result.contentType))
          throw new BuyerResponseFileError('RESPONSE_FILE_BYTE_TYPE_INVALID');
        // Blob snapshots the caller's bytes. This is local serialization, with
        // no fabricated HTTP status, network response or payment outcome.
        body = new Blob([result.bytes]).stream();
        contentType = result.contentType;
      } else {
        const response = result?.response;
        if (!(response instanceof Response) || !response.ok)
          throw new BuyerResponseFileError('RESPONSE_FILE_HTTP_STATUS', 'a returned 2xx Response is required');
        if (response.bodyUsed || response.body?.locked)
          throw new BuyerResponseFileError('RESPONSE_FILE_BODY_UNAVAILABLE', 'save the unread original response');
        body = response.body; contentType = response.headers.get('content-type');
        objectMetadata = {
          contentRange: response.headers.get('content-range'),
          contentSha256: response.headers.get('x-content-sha256'),
          snapshot: response.headers.get('x-sf30-object-snapshot'),
          totalBytes: response.headers.get('x-sf30-object-bytes'),
        };
      }
      // Count the bytes Fetch exposes, not Content-Length: compression can make
      // that header describe a different representation than this stream.
      if (body) reader = body.getReader();
      if (pins.expectedContentType !== undefined &&
          contentType?.split(';', 1)[0].trim().toLowerCase() !== pins.expectedContentType)
        throw new BuyerResponseFileError('RESPONSE_FILE_TYPE_MISMATCH');
      if (parser && !responseStreamContentType(streamOptions.format, contentType))
        throw new BuyerResponseFileError('RESPONSE_STREAM_TYPE_MISMATCH');
      while (reader) {
        check();
        let chunk;
        // One cancellation listener per pending read, removed after that read;
        // no growing chain of Promise.race callbacks on a shared timer promise.
        try { chunk = await readChunk(reader, controller.signal); }
        catch (cause) {
          if (cause instanceof BuyerResponseFileError) throw cause;
          throw new BuyerResponseFileError('RESPONSE_FILE_READ_FAILED', '', { cause });
        }
        const { done, value } = chunk;
        if (done) break;
        if (!(value instanceof Uint8Array)) throw new BuyerResponseFileError('RESPONSE_FILE_BAD_CHUNK');
        if (value.byteLength > maxBytes - bytes)
          throw new BuyerResponseFileError('RESPONSE_FILE_TOO_LARGE', `limit ${maxBytes} bytes`);
        let offset = 0;
        while (offset < value.byteLength) {
          check();
          const { bytesWritten } = await file.write(value, offset, value.byteLength - offset, null);
          if (bytesWritten < 1) throw new BuyerResponseFileError('RESPONSE_FILE_WRITE_FAILED', 'write made no progress');
          hash.update(value.subarray(offset, offset + bytesWritten));
          bytes += bytesWritten;
          offset += bytesWritten;
        }
        if (parser) await emitRecords(parser.push(value));
      }
      if (parser) {
        await emitRecords(parser.finish());
        if (!parser.summary().complete)
          throw new BuyerResponseFileError('RESPONSE_STREAM_INCOMPLETE_RECORD');
      }
      check();
      if (allocation !== null) {
        const current = await file.stat();
        if (current.size !== bytes) throw new BuyerResponseFileError('RESPONSE_FILE_ALLOCATION_SIZE_CHANGED');
        await file.truncate(bytes);
      }
      await file.sync();
      await file.close();
      file = null;
      check();
      digest = hash.digest('hex');
      const saved = { path: finalPath, bytes, sha256: digest, contentType,
        ...(allocation === null ? {} : {allocation}),
        ...(parser ? { stream: parser.summary() } : {}) };
      // A completed transfer is not yet an accepted product. Leave a mismatched
      // private partial for reconciliation; never publish it under the buyer's name.
      if (pins.expectedBytes !== undefined && bytes !== pins.expectedBytes)
        throw new BuyerResponseFileError('RESPONSE_FILE_SIZE_MISMATCH');
      if (pins.expectedSha256 !== undefined && saved.sha256 !== pins.expectedSha256)
        throw new BuyerResponseFileError('RESPONSE_FILE_DIGEST_MISMATCH');
      if (Object.keys(pins).length) saved.verifiedAgainst = { ...pins };
      if (Object.values(objectMetadata).some(value => value !== null))
        saved.objectMetadata = objectMetadata;
      // link is atomic and fails when the destination exists; rename would
      // silently overwrite a file created after the original preflight.
      try { await link(partialPath, finalPath); }
      catch (cause) {
        throw new BuyerResponseFileError(cause.code === 'EEXIST' ? 'RESPONSE_FILE_EXISTS' : 'RESPONSE_FILE_PUBLISH_FAILED', finalPath, { cause });
      }
      complete = true;
      state = 'SAVED';
      clearTimeout(timer);
      const cleanupWarnings = await cleanup();
      return { ...saved, cleanupWarnings };
    } catch (cause) {
      state = 'FAILED';
      if (reader) { try { void reader.cancel().catch(() => {}); } catch {} }
      const cleanupWarnings = await cleanup({ keepPartial: bytes > 0 });
      const error = cause instanceof BuyerResponseFileError ? cause : new BuyerResponseFileError(
        cause instanceof BuyerResponseStreamError ? cause.code : 'RESPONSE_FILE_WRITE_FAILED', '', { cause });
      error.bytes = bytes;
      error.partialPath = bytes > 0 ? partialPath : null;
      error.cleanupWarnings = cleanupWarnings;
      if (parser) {
        error.stream = { ...parser.summary(), complete: false };
        error.partialSha256 = digest ?? hash.digest('hex');
      }
      throw error;
    } finally {
      clearTimeout(timer);
      if (onExternalAbort) signal.removeEventListener('abort', onExternalAbort);
      if (reader) {
        // A remote source's unresolved cancellation must not hold the caller.
        if (!complete) { try { void reader.cancel().catch(() => {}); } catch {} }
        try { reader.releaseLock(); } catch {}
      }
    }
  }

  return Object.freeze({
    destination: finalPath,
    partialPath,
    ...(allocation === null ? {} : {allocation}),
    save(result, { signal, onRecord } = {}) {
      if (state !== 'PREPARED')
        return Promise.reject(new BuyerResponseFileError('RESPONSE_FILE_NOT_PREPARED', state));
      state = 'SAVING';
      activeSave = saveOnce(result, signal, onRecord);
      return activeSave;
    },
    /** Save already-returned non-HTTP bytes through the same reserved writer. */
    saveBytes(bytes, { contentType = 'application/octet-stream', signal } = {}) {
      if (state !== 'PREPARED')
        return Promise.reject(new BuyerResponseFileError('RESPONSE_FILE_NOT_PREPARED', state));
      state = 'SAVING';
      activeSave = saveOnce({ bytes, contentType }, signal, undefined, true);
      return activeSave;
    },
    async abort() {
      if (state === 'SAVING') {
        controller.abort(new BuyerResponseFileError('RESPONSE_FILE_ABORTED'));
        try { await activeSave; } catch {}
      } else if (state === 'PREPARED') {
        state = 'ABORTED';
        const cleanupWarnings = await cleanup();
        if (cleanupWarnings.length)
          throw new BuyerResponseFileError('RESPONSE_FILE_CLEANUP_FAILED', '', { cleanupWarnings });
      }
    },
  });
}

// MIT — Incremental framing for one original HTTP response. No requests or retries.
const LIMIT = 64 * 1024 * 1024;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);

export class BuyerResponseStreamError extends Error {
  constructor(code) { super(code); this.name = 'BuyerResponseStreamError'; this.code = code; }
}
const need = (condition, code) => { if (!condition) throw new BuyerResponseStreamError(code); };

/** Pure configuration validation, suitable before the original paid request. */
export function normalizeResponseStream(value) {
  need(object(value) && Object.keys(value).every(key =>
    ['format', 'maxRecordBytes', 'maxRecords'].includes(key)), 'BAD_RESPONSE_STREAM_OPTIONS');
  const { format, maxRecordBytes = 1048576, maxRecords = 100000 } = value;
  need(['sse', 'ndjson'].includes(format), 'BAD_RESPONSE_STREAM_FORMAT');
  need(Number.isSafeInteger(maxRecordBytes) && maxRecordBytes > 0 && maxRecordBytes <= LIMIT,
    'BAD_RESPONSE_STREAM_RECORD_LIMIT');
  need(Number.isSafeInteger(maxRecords) && maxRecords > 0 && maxRecords <= 1000000,
    'BAD_RESPONSE_STREAM_COUNT_LIMIT');
  return Object.freeze({ format, maxRecordBytes, maxRecords });
}

export function responseStreamContentType(format, value) {
  if (typeof value !== 'string') return false;
  const [type, ...parameters] = value.toLowerCase().split(';').map(part => part.trim());
  const charsets = parameters.filter(part => /^charset\s*=/.test(part));
  if (charsets.length > 1 || charsets.some(part =>
    !/^charset\s*=\s*(?:utf-8|utf8|"utf-8"|"utf8")$/.test(part))) return false;
  return format === 'sse' ? type === 'text/event-stream' : format === 'ndjson' &&
    ['application/x-ndjson', 'application/ndjson'].includes(type);
}

/**
 * Byte-preserving framing. Every returned record belongs to bytes already
 * supplied to push(). SSE follows the standard CR/LF, comment, data, event, id
 * and retry rules; EOF never dispatches an unfinished event. NDJSON requires
 * a newline after each JSON value and ignores empty/whitespace-only lines.
 * UTF-8 is fatal; limits apply to the complete wire record, including framing.
 */
export function createResponseStreamParser(options) {
  const config = normalizeResponseStream(options);
  const { format, maxRecordBytes, maxRecords } = config;
  const decoder = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });
  let lineBuffer = Buffer.allocUnsafe(Math.min(4096, maxRecordBytes));
  let lineBytes = 0, recordBytes = 0, lastRecordBytes = 0, totalBytes = 0;
  let records = 0, emptyLines = 0, complete = false, ended = false, failed = null;
  let firstLine = true, skipLF = false, lastCompleteByte = 0;
  let data = [], dataPresent = false, event = '', lastEventId = '', retryMilliseconds = null;
  const pending = () => lineBytes > 0 || (format === 'sse' && dataPresent);
  const summary = () => Object.freeze({ format, records, bytes: totalBytes,
    complete, pendingRecord: pending(), lastCompleteByte,
    ...(format === 'sse' ? { lastEventId, retryMilliseconds } : { emptyLines }),
    ...(failed ? { error: failed } : {}) });
  function error(code) {
    failed = code;
    const result = new BuyerResponseStreamError(code);
    result.stream = summary();
    throw result;
  }
  function append(piece) {
    if (piece.length === 0) return;
    if (piece.length > maxRecordBytes - recordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE');
    const size = lineBytes + piece.length;
    if (size > lineBuffer.length) {
      const next = Buffer.allocUnsafe(Math.min(maxRecordBytes, Math.max(size, lineBuffer.length * 2)));
      lineBuffer.copy(next, 0, 0, lineBytes); lineBuffer = next;
    }
    lineBuffer.set(piece, lineBytes); lineBytes = size; recordBytes += piece.length;
  }
  function record(value, output) {
    if (records >= maxRecords) error('RESPONSE_STREAM_TOO_MANY_RECORDS');
    records++;
    output.push(Object.freeze({ index: records - 1, ...value }));
  }
  function line(output) {
    let text;
    try { text = decoder.decode(lineBuffer.subarray(0, lineBytes)); }
    catch { error('RESPONSE_STREAM_UTF8_INVALID'); }
    lineBytes = 0;
    if (firstLine) { firstLine = false; if (text.startsWith('\ufeff')) text = text.slice(1); }
    if (format === 'ndjson') {
      if (text.endsWith('\r')) text = text.slice(0, -1);
      if (text.includes('\r')) error('RESPONSE_STREAM_JSON_INVALID');
      if (text.trim().length === 0) emptyLines++;
      else {
        let value;
        try { value = JSON.parse(text); } catch { error('RESPONSE_STREAM_JSON_INVALID'); }
        record({ format, value }, output);
      }
      recordBytes = 0; lastCompleteByte = totalBytes;
      return;
    }
    if (text === '') {
      if (dataPresent) record({ format, event: event || 'message', data: data.join('\n'),
        id: lastEventId, ...(retryMilliseconds === null ? {} : { retry: retryMilliseconds }) }, output);
      else emptyLines++;
      data = []; dataPresent = false; event = ''; lastRecordBytes = recordBytes;
      recordBytes = 0; lastCompleteByte = totalBytes;
      return;
    }
    if (text.startsWith(':')) return;
    const colon = text.indexOf(':');
    const field = colon === -1 ? text : text.slice(0, colon);
    let value = colon === -1 ? '' : text.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    if (field === 'data') { data.push(value); dataPresent = true; }
    else if (field === 'event') event = value;
    else if (field === 'id' && !value.includes('\0')) lastEventId = value;
    else if (field === 'retry' && /^[0-9]+$/.test(value) && Number.isSafeInteger(Number(value)))
      retryMilliseconds = Number(value);
  }
  function push(value) {
    need(!ended && failed === null, 'RESPONSE_STREAM_PARSER_CLOSED');
    need(value instanceof Uint8Array, 'RESPONSE_STREAM_BAD_CHUNK');
    const bytes = Buffer.from(value.buffer, value.byteOffset, value.byteLength), output = [];
    let start = 0;
    for (let i = 0; i < bytes.length; i++) {
      const byte = bytes[i];
      if (skipLF) {
        skipLF = false;
        if (byte === 10) { totalBytes++; start = i + 1;
          if (recordBytes === 0) {
            if (++lastRecordBytes > maxRecordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE');
            lastCompleteByte = totalBytes;
          }
          else { if (++recordBytes > maxRecordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE'); }
          continue;
        }
      }
      if (byte !== 10 && (format !== 'sse' || byte !== 13)) continue;
      append(bytes.subarray(start, i));
      totalBytes += i - start + 1;
      if (++recordBytes > maxRecordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE');
      line(output);
      skipLF = format === 'sse' && byte === 13;
      start = i + 1;
    }
    append(bytes.subarray(start)); totalBytes += bytes.length - start;
    return output;
  }
  function finish() {
    need(!ended && failed === null, 'RESPONSE_STREAM_PARSER_CLOSED');
    ended = true;
    // Validate even the undispatched tail. Do not emit it as a completed record.
    if (lineBytes) {
      try { decoder.decode(lineBuffer.subarray(0, lineBytes)); }
      catch { error('RESPONSE_STREAM_UTF8_INVALID'); }
    }
    complete = !pending();
    return [];
  }
  return Object.freeze({ push, finish, summary, options: config });
}

/** Decode retained bytes or one live body with normal async-iterator backpressure. */
export async function* parseResponseStream(chunks, { signal, ...options }) {
  need(signal === undefined || signal instanceof AbortSignal, 'BAD_RESPONSE_STREAM_SIGNAL');
  const parser = createResponseStreamParser(options);
  for await (const chunk of chunks) {
    need(!signal?.aborted, 'RESPONSE_STREAM_ABORTED');
    yield* parser.push(chunk);
  }
  need(!signal?.aborted, 'RESPONSE_STREAM_ABORTED');
  yield* parser.finish();
  if (!parser.summary().complete) {
    const error = new BuyerResponseStreamError('RESPONSE_STREAM_INCOMPLETE_RECORD');
    error.stream = parser.summary();
    throw error;
  }
}

/**
 * SF85 opt-in HTTPS over an explicitly approved HTTP CONNECT proxy.
 * No request path, merchant challenge headers or credentials reach the proxy in
 * plaintext. A single tunnel carries one original TLS-verified HTTP request.
 * SPDX-License-Identifier: MIT
 */
import { Agent as HttpsAgent } from 'node:https';
import { request as httpRequest } from 'node:http';
import { connect as tlsConnect, checkServerIdentity } from 'node:tls';

function proxyError(code) {
  const error = new Error(code);
  error.code = code;
  return error;
}

export function parseExplicitProxy(raw) {
  if (typeof raw !== 'string' || raw.length > 2048) throw proxyError('INVALID_EXPLICIT_PROXY');
  let url;
  try { url = new URL(raw); } catch { throw proxyError('INVALID_EXPLICIT_PROXY'); }
  if (url.protocol !== 'http:' || !url.hostname || url.username || url.password ||
      url.search || url.hash || (url.pathname && url.pathname !== '/') ||
      (url.port && (!Number.isInteger(Number(url.port)) || Number(url.port) < 1 || Number(url.port) > 65535))) {
    throw proxyError('PROXY_MUST_BE_HTTP_HOST_PORT_WITHOUT_CREDENTIALS');
  }
  // Explicit local/VM proxies are legitimate; never trust implicit env proxies.
  // HTTP CONNECT only; target URL/approval and TLS verification stay upstream.
  return { hostname: url.hostname.replace(/^\[|\]$/g, ''), port: Number(url.port || '80') };
}

/**
 * Obtain a single-use https.Agent that constructs an HTTP CONNECT tunnel and
 * performs TLS with the ORIGINAL seller hostname, not the proxy hostname.
 *
 * Proxy CONNECT authority uses a validated pinned PUBLIC IPv4:443 by default.
 * Trusted VM overlay DNS (explicit 198.18/15 option upstream) requires the
 * original hostname:443, since the gateway's 198.18 address speaks plain HTTP
 * outside its forward-proxy CONNECT routing path.
 * An explicitly trusted resolving proxy may also receive the original hostname
 * without local DNS, via resolveAtProxy:true. Its caller must pin the origin.
 */
export function oneShotConnectAgent({ target, proxy, pinnedIP, sandboxOverlay, resolveAtProxy = false, signal },
                                    { openConnect = httpRequest, openTls = tlsConnect } = {}) {
  if (!target || !proxy || (!resolveAtProxy && !pinnedIP) || !signal ||
      typeof resolveAtProxy !== 'boolean') throw proxyError('PROXY_CONFIG_INCOMPLETE');
  const authority = (sandboxOverlay || resolveAtProxy ? target.hostname : pinnedIP) + ':443';
  const agent = new HttpsAgent({ keepAlive: false, maxSockets: 1 });
  let pendingConnect;
  let tunnelSocket;
  let tlsSocket;
  let finished = false;
  const onAbort = () => {
    pendingConnect?.destroy(proxyError('PROXY_CAPTURE_TIMEOUT'));
    tlsSocket?.destroy(proxyError('PROXY_CAPTURE_TIMEOUT'));
    tunnelSocket?.destroy();
  };
  signal.addEventListener('abort', onAbort, { once: true });
  const stop = () => {
    if (!finished) {
      finished = true;
      signal.removeEventListener('abort', onAbort);
      pendingConnect?.destroy();
      tlsSocket?.destroy();
      tunnelSocket?.destroy();
      agent.destroy();
    }
  };
  agent.createConnection = (_connectionOptions, done) => {
    let settled = false;
    const complete = (error, socket) => {
      if (settled) return;
      settled = true;
      if (error) {
        tlsSocket?.destroy();
        tunnelSocket?.destroy();
      }
      done(error, socket);
    };
    try {
      pendingConnect = openConnect({
        hostname: proxy.hostname, port: proxy.port,
        method: 'CONNECT', path: authority, agent: false,
        headers: { Host: authority },
        // HTTP proxy is named explicitly by the operator; auth is forbidden.
      });
      pendingConnect.once('connect', (response, socket, head) => {
        tunnelSocket = socket;
        if (response.statusCode !== 200 || head.length !== 0) {
          complete(proxyError('PROXY_CONNECT_NOT_ESTABLISHED'));
          return;
        }
        tlsSocket = openTls({
          socket,
          servername: target.hostname,
          rejectUnauthorized: true,
          checkServerIdentity,
          minVersion: 'TLSv1.2',
          ALPNProtocols: ['http/1.1'],
        });
        tlsSocket.once('secureConnect', () => {
          if (!tlsSocket.authorized) {
            complete(proxyError('MERCHANT_TLS_NOT_AUTHORIZED'));
            return;
          }
          complete(null, tlsSocket);
        });
        tlsSocket.once('error', (error) => complete(error));
      });
      pendingConnect.once('response', (response) => {
        response.resume();
        complete(proxyError('PROXY_CONNECT_NOT_ESTABLISHED'));
      });
      pendingConnect.once('error', (error) => complete(error));
      pendingConnect.end();
      if (signal.aborted) onAbort();
    } catch (error) { complete(error); }
  };
  return { agent, stop };
}

// MIT. Private original SF88 HTTP/signing checkpoints; SF31/SF81 retain payment authority.
import { lstat, open, readdir, rename } from './dataset-location.mjs';
import { constants } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { isDeepStrictEqual } from 'node:util';
import { readNativeSigningDiagnostic } from '../sf103-native-buyer-signer/diagnostics.mjs';
import {
  BuyerError, digest, now, parseJson, jsonBytes, need, absolute,
} from './node/store.mjs';
import {datasetPrivateStateDirectory as privateDirectory,datasetReadStateBytes as readBytes,
  datasetWriteStateBytes as writeBytes,datasetStateExists as exists,
  datasetPrepareWriteReservations as prepareWriteReservations,
  datasetSyncStateDirectory as syncDirectory} from './dataset-location.mjs';

const SCHEMA = 'stellar-forge.sf88.attempt-wire.v1';
const SOURCE_LIMIT = 2_000_000;
const RECORD_LIMIT = 300_000;
const same = isDeepStrictEqual;
const canonical = value => value === null || typeof value !== 'object' ? value :
  Array.isArray(value) ? value.map(canonical) :
    Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])]));
const valueHash = value => digest(Buffer.from(JSON.stringify(canonical(value))));
const code = (error, fallback) => /^[A-Z0-9_]{1,120}$/.test(error?.code ?? '') ? error.code : fallback;
const wirePath = cfg => join(cfg.evidenceDir, 'wire-' + digest(Buffer.from(cfg.operation.intentId)));
const EVENTS = [
  'unsigned-request', 'unsigned-dispatch', 'unsigned-response', 'unsigned-error',
  'signing-input', 'signing-result', 'signing-error',
  'signed-request', 'signed-dispatch', 'signed-response', 'signed-error',
];

// Same private descriptor/flock ownership used by the original Node workspace.
// Readers take this lock without creating it, so an active writer cannot be
// mistaken for a stopped attempt between two checkpoint publications.
async function ownership(directory, create, name = 'active.lock') {
  const path=join(directory,name);
  const handle=await open(path,constants.O_RDWR | (create ? constants.O_CREAT : 0) |
    (constants.O_NOFOLLOW ?? 0),0o600);
  try {
    const file=await handle.stat(),named=await lstat(path);
    need(file.isFile() && file.nlink===1 && !(file.mode&0o077) &&
      file.dev===named.dev && file.ino===named.ino && !named.isSymbolicLink() &&
      (!process.getuid || file.uid===process.getuid()),'WIRE_LOCK_CHANGED');
    const result=spawnSync('flock',['--exclusive','--nonblock','--conflict-exit-code','73','3'],
      {stdio:['ignore','pipe','pipe',handle.fd],timeout:10000});
    if (!result.error && result.status===73) {await handle.close();return null;}
    need(!result.error && result.status===0,'WIRE_FLOCK_REQUIRED');
    return handle;
  } catch(error) {await handle.close();throw error;}
}

async function originalFile(path, limit) {
  const info = await lstat(path);
  need(info.isFile() && !info.isSymbolicLink() &&
    (process.platform === 'win32' || ((info.mode & 0o077) === 0 &&
      (!process.getuid || info.uid === process.getuid()))), 'WIRE_PRIVATE_FILE_REQUIRED');
  const raw = await readBytes(path, limit);
  return { raw, value: parseJson(raw), sha256: digest(raw), bytes: raw.length };
}

function requestBody(value) {
  if (value === undefined || value === null) return {present:false, bytes:Buffer.alloc(0)};
  need(typeof value === 'string' || value instanceof Uint8Array, 'WIRE_REPLAYABLE_BODY_REQUIRED');
  const bytes = Buffer.from(value);
  need(bytes.length <= 1_048_576, 'WIRE_BODY_TOO_LARGE');
  return {present:true, bytes};
}
function bindingFor(cfg, body) {
  const operation = cfg.operation;
  need(operation && typeof operation.intentId === 'string' &&
    /^[A-Za-z0-9._:-]{1,160}$/.test(operation.intentId), 'WIRE_OPERATION_REQUIRED');
  return {
    intentId:operation.intentId, url:new URL(operation.url).href, method:operation.method ?? 'GET',
    configValueSha256:valueHash(cfg),
    bodyPresent:body.present, bodyBytes:body.bytes.length, bodySha256:digest(body.bytes),
  };
}
function headerEntries(headers) {
  const result = [...new Headers(headers).entries()];
  need(Buffer.byteLength(JSON.stringify(result)) <= 262_144, 'WIRE_HEADERS_TOO_LARGE');
  return result;
}
function stateOf(events) {
  if (events['signed-response']) return 'SIGNED_RESPONSE_HEADERS_RETAINED';
  if (events['signed-error']) return 'SIGNED_TRANSPORT_ERROR_RETAINED';
  if (events['signed-dispatch']) return 'SIGNED_DISPATCH_OUTCOME_UNRESOLVED';
  if (events['signed-request']) return 'SIGNED_REQUEST_NOT_DISPATCHED';
  if (events['signing-result']) return 'SIGNER_RESULT_RETAINED_NOT_DISPATCHED';
  if (events['signing-error']) return 'SIGNING_ERROR_RETAINED';
  if (events['signing-input']) return 'SIGNING_STARTED_NOT_DISPATCHED';
  if (events['unsigned-response']) return 'UNSIGNED_RESPONSE_HEADERS_RETAINED';
  if (events['unsigned-error']) return 'UNSIGNED_TRANSPORT_ERROR_RETAINED';
  if (events['unsigned-dispatch']) return 'UNSIGNED_DISPATCH_OUTCOME_UNRESOLVED';
  if (events['unsigned-request']) return 'UNSIGNED_REQUEST_NOT_DISPATCHED';
  return 'SOURCE_RETAINED';
}
function view(directory, source, events, writerActive = false) {
  const nativeSigning=readNativeSigningDiagnostic(events['signing-error']?.value.nativeSigning);
  return {
    schema:SCHEMA, intentId:source.value.binding.intentId, directory, writerActive,
    sourceSha256:source.sha256, configValueSha256:source.value.binding.configValueSha256,
    state:stateOf(events), signingEntered:!!events['signing-input'],
    signedDispatchRecorded:!!events['signed-dispatch'],
    signedResponseRecorded:!!events['signed-response'],
    ...(nativeSigning ? {nativeSigning} : {}),
    records:Object.fromEntries(Object.entries(events).map(([name, item]) =>
      [name, {path:join(directory, name + '.json'),sha256:item.sha256,bytes:item.bytes,
        recordedAt:item.value.recordedAt}])),
    response:events['signed-response'] ? {
      status:events['signed-response'].value.status,
      headersSha256:valueHash(events['signed-response'].value.headers),
    } : null,
  };
}

/** Called once by original execute before the buyer/approval/signer can run.
 * All wire payloads remain in the caller's existing private evidence directory.
 * No socket, signer, approval or ledger capability is provided by this module. */
export async function createAttemptWireRecorder({cfg, body, fetchImpl, reserveFile, signal}) {
  need(typeof fetchImpl === 'function', 'WIRE_ORIGINAL_TRANSPORT_REQUIRED');
  const frozen = JSON.parse(JSON.stringify(cfg));
  const originalBody = requestBody(body);
  const binding = bindingFor(frozen, originalBody);
  await privateDirectory(frozen.evidenceDir, {create:false});
  const directory = await privateDirectory(wirePath(frozen));
  const sourceValue = {
    schema:SCHEMA, binding, recordedAt:now(), config:frozen,
    requestBodyBase64:originalBody.present ? originalBody.bytes.toString('base64') : null,
  };
  const sourceRaw = jsonBytes(sourceValue);
  need(sourceRaw.length <= SOURCE_LIMIT, 'WIRE_SOURCE_TOO_LARGE');
  const held = await ownership(directory,true);
  need(held,'WIRE_ATTEMPT_ACTIVE');
  let reservations;
  try {
    // These are the actual future checkpoint inodes, held before approval or signing.
    reservations = await prepareWriteReservations([
      {path:join(directory,'source.json'),bytes:sourceRaw.length,exclusive:true},
      ...EVENTS.map(name=>({path:join(directory,name+'.json'),bytes:RECORD_LIMIT,exclusive:true})),
    ], {reserveFile,signal});
    if (reservations) await reservations.writeBytes(join(directory,'source.json'),sourceRaw,{exclusive:true});
    else await writeBytes(join(directory,'source.json'),sourceRaw,{exclusive:true});
  } catch (error) {
    try { await reservations?.close(); } finally { await held.close(); }
    if (error.code === 'EEXIST') throw new BuyerError('WIRE_ATTEMPT_ALREADY_RECORDED_USE_RECOVERY');
    throw error;
  }
  const source = {raw:sourceRaw, value:sourceValue, sha256:digest(sourceRaw),bytes:sourceRaw.length};
  const events = Object.create(null);
  let closed=false;
  async function publish(name, fields) {
    need(!closed && EVENTS.includes(name) && !events[name], 'WIRE_PHASE_ALREADY_RECORDED');
    const raw = jsonBytes({schema:SCHEMA, intentId:binding.intentId, sourceSha256:source.sha256,
      phase:name, recordedAt:now(), ...fields});
    const value = parseJson(raw);
    need(raw.length <= RECORD_LIMIT, 'WIRE_RECORD_TOO_LARGE');
    if (reservations) await reservations.writeBytes(join(directory,name+'.json'),raw,{exclusive:true});
    else await writeBytes(join(directory,name+'.json'),raw,{exclusive:true});
    events[name] = {raw,value,sha256:digest(raw),bytes:raw.length};
    return events[name];
  }
  async function signingInput(input) {
    need(input?.intent?.intentId === binding.intentId && input.intent.url === binding.url &&
      input.intent.method === binding.method && input.intent.bodyPresent === binding.bodyPresent &&
      input.intent.bodyBytes === binding.bodyBytes && input.intent.bodySha256 === binding.bodySha256,
      'WIRE_SIGNING_REQUEST_MISMATCH');
    need(events['unsigned-response']?.value.status === 402 && !events['signing-input'],
      'WIRE_SIGNING_PHASE_MISMATCH');
    await publish('signing-input', {input, inputSha256:digest(Buffer.from(JSON.stringify(input.intent)))});
  }
  async function signingResult(result) {
    need(events['signing-input'] && !events['signing-result'] && !events['signing-error'],
      'WIRE_SIGNING_PHASE_MISMATCH');
    await publish('signing-result', {inputSha256:events['signing-input'].sha256,
      payload:result, payloadSha256:digest(Buffer.from(JSON.stringify(result)))});
  }
  async function signingError(error) {
    if (!events['signing-input'] || events['signing-result'] || events['signing-error']) return;
    let nativeSigning;
    try { nativeSigning=readNativeSigningDiagnostic(error?.nativeSigning); } catch {}
    await publish('signing-error', {inputSha256:events['signing-input'].sha256,
      code:code(error, 'ORIGINAL_SIGNER_ERROR'), ...(nativeSigning ? {nativeSigning} : {})});
  }
  async function fetch(url, options = {}) {
    const href = new URL(url).href, method = options.method ?? 'GET';
    const currentBody = requestBody(options.body);
    need(href === binding.url && method === binding.method &&
      currentBody.present === binding.bodyPresent && currentBody.bytes.equals(originalBody.bytes),
      'WIRE_REQUEST_BINDING_MISMATCH');
    const headers = headerEntries(options.headers);
    const signature = headers.find(([name]) => name === 'payment-signature')?.[1];
    const leg = signature === undefined ? 'unsigned' : 'signed';
    need(!events[leg + '-request'], 'WIRE_PHASE_ALREADY_RECORDED');
    if (leg === 'signed') {
      const result = events['signing-result'];
      need(result && Buffer.from(JSON.stringify(result.value.payload)).toString('base64') === signature,
        'WIRE_SIGNED_PAYLOAD_MISMATCH');
      const unsigned = events['unsigned-request']?.value;
      need(unsigned && same(headers.filter(([name]) => name !== 'payment-signature'), unsigned.headers),
        'WIRE_REQUEST_HEADERS_CHANGED');
    } else need(!events['signing-input'], 'WIRE_PHASE_ORDER_INVALID');
    const requested = await publish(leg + '-request', {
      url:href, method, headers, bodyPresent:binding.bodyPresent,
      bodyBytes:binding.bodyBytes, bodySha256:binding.bodySha256,
      ...(leg === 'signed' ? {signingResultSha256:events['signing-result'].sha256} : {}),
    });
    // This immutable marker is durable before the original transport may open a
    // socket. Its presence is an attempted dispatch, never proof of delivery.
    await publish(leg + '-dispatch', {requestSha256:requested.sha256});
    let response;
    try { response = await fetchImpl(url, options); }
    catch (error) {
      try { await publish(leg + '-error', {requestSha256:requested.sha256,
        code:code(error, 'ORIGINAL_TRANSPORT_ERROR')}); } catch {}
      throw error;
    }
    try {
      await publish(leg + '-response', {
        requestSha256:requested.sha256, status:response.status,
        statusText:response.statusText, url:response.url || href,
        headers:headerEntries(response.headers),
      });
    } catch (error) {
      // The original request may have been paid. SF31 preserves its signed-leg
      // uncertainty on this error; a failed checkpoint never authorizes retry.
      try { await response.body?.cancel(); } catch {}
      throw error;
    }
    return response;
  }
  return Object.freeze({fetch,signingInput,signingResult,signingError,
    async close(){if(!closed){closed=true;try{await reservations?.close();}finally{await held.close();}}},
    snapshot:() => view(directory,source,events,!closed)});
}

/** Read-only source validation. includeWire is for the original private recovery
 * consumer: it exposes signed authorization bytes and must never be logged,
 * exported to a public artifact, or sent to a different merchant. */
async function checkpointWithLock({cfg, body, includeWire = false}, directory) {
  need(typeof includeWire === 'boolean', 'WIRE_INCLUDE_OPTION_INVALID');
  const source = await originalFile(join(directory,'source.json'),SOURCE_LIMIT);
  const binding = bindingFor(cfg,requestBody(body));
  need(source.value.schema === SCHEMA && same(source.value.binding,binding) &&
    valueHash(source.value.config) === binding.configValueSha256, 'WIRE_SOURCE_BINDING_MISMATCH');
  const retainedBody = source.value.requestBodyBase64;
  need(retainedBody === null ? !binding.bodyPresent :
    typeof retainedBody === 'string' && binding.bodyPresent &&
      Buffer.from(retainedBody,'base64').length === binding.bodyBytes &&
      digest(Buffer.from(retainedBody,'base64')) === binding.bodySha256, 'WIRE_BODY_BINDING_MISMATCH');
  const events = Object.create(null);
  for (const name of EVENTS) {
    const path = join(directory,name+'.json');
    if (!await exists(path)) continue;
    const event = await originalFile(path,RECORD_LIMIT), value = event.value;
    need(value.schema === SCHEMA && value.intentId === binding.intentId &&
      value.sourceSha256 === source.sha256 && value.phase === name &&
      Number.isFinite(Date.parse(value.recordedAt)), 'WIRE_RECORD_BINDING_MISMATCH');
    events[name] = event;
  }
  for (const leg of ['unsigned','signed']) {
    const request = events[leg+'-request'];
    for (const suffix of ['dispatch','response','error']) {
      const event = events[leg+'-'+suffix];
      need(!event || request && event.value.requestSha256 === request.sha256,
        'WIRE_REQUEST_RECORD_MISMATCH');
      if (suffix !== 'dispatch') need(!event || events[leg+'-dispatch'], 'WIRE_DISPATCH_RECORD_MISSING');
    }
    need(!(events[leg+'-response'] && events[leg+'-error']), 'WIRE_CONTRADICTORY_RESPONSE');
    if (request) need(request.value.url === binding.url && request.value.method === binding.method &&
      request.value.bodyPresent === binding.bodyPresent && request.value.bodyBytes === binding.bodyBytes &&
      request.value.bodySha256 === binding.bodySha256, 'WIRE_REQUEST_BINDING_MISMATCH');
  }
  const input=events['signing-input'],signed=events['signing-result'],signedRequest=events['signed-request'];
  if (input) need(events['unsigned-response']?.value.status === 402 &&
    input.value.input?.intent?.intentId === binding.intentId &&
    input.value.input.intent.url === binding.url && input.value.input.intent.method === binding.method &&
    input.value.input.intent.bodyPresent === binding.bodyPresent &&
    input.value.input.intent.bodyBytes === binding.bodyBytes &&
    input.value.input.intent.bodySha256 === binding.bodySha256 &&
    digest(Buffer.from(JSON.stringify(input.value.input.intent))) === input.value.inputSha256,
    'WIRE_SIGNING_RECORD_MISMATCH');
  if (signed) need(input && signed.value.inputSha256 === input.sha256 &&
    digest(Buffer.from(JSON.stringify(signed.value.payload))) === signed.value.payloadSha256,
    'WIRE_SIGNATURE_RECORD_MISMATCH');
  if (events['signing-error']) {
    const errorRecord=events['signing-error'].value;
    need(input && !signed && errorRecord.inputSha256 === input.sha256, 'WIRE_SIGNING_RECORD_MISMATCH');
    if (Object.hasOwn(errorRecord,'nativeSigning')) need(
      readNativeSigningDiagnostic(errorRecord.nativeSigning) !== undefined,
      'WIRE_SIGNING_DIAGNOSTIC_INVALID');
  }
  if (signedRequest) need(signed && signedRequest.value.signingResultSha256 === signed.sha256 &&
    signedRequest.value.headers.find(([name]) => name === 'payment-signature')?.[1] ===
      Buffer.from(JSON.stringify(signed.value.payload)).toString('base64') &&
    same(signedRequest.value.headers.filter(([name]) => name !== 'payment-signature'),
      events['unsigned-request']?.value.headers), 'WIRE_SIGNED_PAYLOAD_MISMATCH');
  const snapshot=view(directory,source,events);
  if(!includeWire) return snapshot;
  // Private capabilities remain directly accessible to the original recovery
  // consumer, while normal JSON/console projections expose only the snapshot.
  return Object.defineProperties({snapshot},{
    source:{value:source.value},
    events:{value:Object.fromEntries(Object.entries(events).map(([name,item]) => [name,item.value]))},
  });
}

export async function readAttemptWireCheckpoint({cfg, body, includeWire = false}) {
  need(typeof includeWire === 'boolean', 'WIRE_INCLUDE_OPTION_INVALID');
  const directory = wirePath(cfg);
  if (!await exists(directory)) return null;
  await privateDirectory(cfg.evidenceDir, {create:false});
  await privateDirectory(directory, {create:false});
  const held=await ownership(directory,false);
  if(!held) return {schema:SCHEMA,intentId:cfg.operation.intentId,directory,
    state:'WRITER_ACTIVE',writerActive:true};
  try { return await checkpointWithLock({cfg,body,includeWire},directory); }
  finally { await held.close(); }
}


const PREAPPROVAL_WIRE = 'stellar-forge.sf88.preapproval-wire.v1';
const HASH = /^[a-f0-9]{64}$/;
const HISTORY_LIMIT = 262144;
const wireCheck = signal => {
  need(signal === undefined || signal instanceof AbortSignal,'INVALID_ABORT_SIGNAL');
  need(!signal?.aborted,'OPERATION_ABORTED_BEFORE_START');
};
function checkpointHash(value) {
  const {sha256,...body}=value;
  return valueHash(body);
}
function missingWire(cfg,body) {
  const value={schema:PREAPPROVAL_WIRE+'.checkpoint',directory:wirePath(cfg),
    binding:bindingFor(cfg,body),exists:false,state:'WIRE_DIRECTORY_ABSENT',files:[]};
  return {...value,sha256:checkpointHash(value)};
}
async function inventoryFile(directory,name) {
  need(name==='active.lock' || name==='source.json' || EVENTS.some(event=>name===event+'.json') ||
    /^\.write-[a-f0-9-]+$/.test(name),'PREAPPROVAL_WIRE_UNKNOWN_MEMBER');
  const path=join(directory,name),fd=await open(path,constants.O_RDONLY|(constants.O_NOFOLLOW??0));
  try {
    const before=await fd.stat();
    need(before.isFile() && before.size<=SOURCE_LIMIT && !(before.mode&0o077) &&
      (!process.getuid || before.uid===process.getuid()),'WIRE_PRIVATE_FILE_REQUIRED');
    const raw=await fd.readFile(),after=await fd.stat(),named=await lstat(path);
    need(raw.length===before.size && before.dev===after.dev && before.ino===after.ino &&
      before.size===after.size && before.mtimeMs===after.mtimeMs && before.ctimeMs===after.ctimeMs &&
      named.dev===after.dev && named.ino===after.ino && !named.isSymbolicLink(),
      'PREAPPROVAL_WIRE_SOURCE_CHANGED');
    return {name,bytes:raw.length,sha256:digest(raw),device:before.dev,inode:before.ino};
  } finally {await fd.close();}
}
async function releaseUnpublishedWireCapacity(directory,checkpoint) {
  for(const expected of checkpoint.files) {
    if(!/^\.write-[a-f0-9-]+$/.test(expected.name))continue;
    // A killed original Store writer cannot close its preallocated future
    // checkpoint slots. Retain each exact inode and all logical bytes while
    // releasing only its abandoned KEEP_SIZE allocation beyond logical EOF.
    need(same(await inventoryFile(directory,expected.name),expected),
      'PREAPPROVAL_WIRE_SOURCE_CHANGED');
    const path=join(directory,expected.name);
    const fd=await open(path,constants.O_RDWR|(constants.O_NOFOLLOW??0));
    try {
      const before=await fd.stat(),named=await lstat(path);
      need(before.isFile() && !named.isSymbolicLink() && !(before.mode&0o077) &&
        (!process.getuid || before.uid===process.getuid()) &&
        before.dev===expected.device && before.ino===expected.inode &&
        before.size===expected.bytes && named.dev===before.dev && named.ino===before.ino,
        'PREAPPROVAL_WIRE_SOURCE_CHANGED');
      await fd.truncate(expected.bytes);
      await fd.sync();
      const raw=await fd.readFile(),after=await fd.stat(),finalName=await lstat(path);
      need(raw.length===expected.bytes && digest(raw)===expected.sha256 &&
        after.dev===before.dev && after.ino===before.ino && after.size===before.size &&
        finalName.dev===after.dev && finalName.ino===after.ino && !finalName.isSymbolicLink(),
        'PREAPPROVAL_WIRE_SOURCE_CHANGED');
    } finally {await fd.close();}
  }
}
async function captureWire(cfg,body,directory,held) {
  const before=await lstat(directory);
  need(before.isDirectory() && !before.isSymbolicLink(),'WIRE_PRIVATE_DIRECTORY_REQUIRED');
  const names=(await readdir(directory)).sort();
  need(names.length<=64,'PREAPPROVAL_WIRE_INVENTORY_LIMIT');
  if(!held) {
    need(names.length===0,'PREAPPROVAL_WIRE_LOCK_REQUIRED');
    const value={schema:PREAPPROVAL_WIRE+'.checkpoint',directory:wirePath(cfg),
      binding:bindingFor(cfg,body),exists:true,directoryIdentity:{device:before.dev,inode:before.ino},
      lockIdentity:null,state:'EMPTY_BEFORE_LOCK',files:[]};
    return {...value,sha256:checkpointHash(value)};
  }
  const lock=await held.stat(),namedLock=await lstat(join(directory,'active.lock'));
  need(lock.dev===namedLock.dev && lock.ino===namedLock.ino,'WIRE_LOCK_CHANGED');
  const files=[];
  for(const name of names)files.push(await inventoryFile(directory,name));
  need(files.reduce((sum,file)=>sum+file.bytes,0)<=16*1024*1024,'PREAPPROVAL_WIRE_INVENTORY_LIMIT');
  need(!names.some(name=>name.startsWith('signing-')||name.startsWith('signed-')),
    'PREAPPROVAL_WIRE_SIGNING_OR_DISPATCH_RECORDED');
