export async function createNativeFileReservation(value) {
  const descriptor = normalizeNativeFileReservation(value);
  need(descriptor, 'NATIVE_FILE_RESERVATION_DESCRIPTOR_REQUIRED');
  const initial = await openExecutable(descriptor.executable, descriptor.executableSha256);
  await initial.handle.close();
  return async function reserveFile({ fileHandle, path, kind, bytes, signal }) {
    need(typeof kind === 'string' && /^[a-z][a-z0-9-]{0,79}$/.test(kind),
      'NATIVE_FILE_RESERVATION_KIND_INVALID');
    need(Number.isSafeInteger(bytes) && bytes > 0 && bytes <= MAX_RESERVATION_BYTES,
      'NATIVE_FILE_RESERVATION_BYTES_INVALID');
    need(signal === undefined || signal instanceof AbortSignal, 'INVALID_ABORT_SIGNAL');
    need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
    path = absolute(path);
    const fd = fileHandle?.fd;
    const before = await targetIdentity(fileHandle, path, fd);
    const selected = await openExecutable(descriptor.executable, descriptor.executableSha256);
    let allocationError;
    try {
      await targetIdentity(fileHandle, path, fd, before);
      await runAllocation(selected.handle, fileHandle, bytes, descriptor.timeoutMs, signal);
    } catch (error) { allocationError = error; }
    finally { await selected.handle.close(); }
    // Even a failed allocation must not change the descriptor or logical EOF.
    // The caller releases any partial extents and remains the descriptor owner.
    await targetIdentity(fileHandle, path, fd, before);
    if (allocationError) throw allocationError;
    need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
    return Object.freeze({ schema: FILE_RESERVATION_SCHEMA, kind, bytes,
      executableSha256: descriptor.executableSha256 });
  };
}

// MIT — Complete native failures stay beside the private command that produced them.
import { inspect } from 'node:util';
import { dirname, join } from 'node:path';
import { absolute, privateDirectory, readBytes, writeBytes, jsonBytes, digest,
  need, safeCode } from './store.mjs';

const SCHEMA = 'stellar-forge.node-inbox-diagnostic.v1';
const classes = new Set(['Error', 'SyntaxError', 'TypeError', 'RangeError',
  'ReferenceError', 'URIError', 'EvalError', 'AggregateError', 'BuyerError', 'InputError']);
const filenames = { COMMAND:'native-error.json', WORKER:'worker-error.json' };
const field = (value, key) => {
  try { return value?.[key]; } catch { return undefined; }
};
const text = value => typeof value === 'string' ? value : null;
const errorClass = problem => classes.has(field(problem, 'name')) ? field(problem, 'name') : 'Error';
function privateInspection(value) {
  try {
    return inspect(value, { depth:null, colors:false, customInspect:false, getters:false,
      maxArrayLength:null, maxStringLength:null, breakLength:120 });
  } catch { return '[Value could not be inspected]'; }
}

/** Full strings and cause/aggregate identities, including circular cause graphs. */
function privateErrorGraph(problem) {
  const seen = new Map(), pending = [], nodes = [];
  const reference = value => {
    if (value !== null && ['object','function'].includes(typeof value)) {
      if (!seen.has(value)) {
        seen.set(value, seen.size + 1);
        pending.push(value);
      }
      return { ref:seen.get(value) };
    }
    return { type:value === null ? 'null' : typeof value,
      value:typeof value === 'string' ? value : privateInspection(value) };
  };
  const root = reference(problem);
  for (let index = 0; index < pending.length; index += 1) {
    const value = pending[index], cause = field(value, 'cause'), errors = field(value, 'errors');
    nodes.push({
      id:seen.get(value), name:text(field(value, 'name')), message:text(field(value, 'message')),
      stack:text(field(value, 'stack')), code:privateInspection(field(value, 'code')),
      cause:cause === undefined ? null : reference(cause),
      errors:Array.isArray(errors) ? errors.map(reference) : null,
      inspection:privateInspection(value),
    });
  }
  return { root, nodes };
}

async function observedSource(file) {
  try {
    const bytes = await readBytes(file, 16777216);
    return { file, bytes:bytes.length, sha256:digest(bytes) };
  } catch (problem) {
    return { file, errorCode:safeCode(problem?.code, 'DIAGNOSTIC_SOURCE_UNAVAILABLE') };
  }
}

/** Only this small allowlisted reference is suitable for routine application logs. */
export function normalizeInboxDiagnostic(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value) ||
      value.schema !== SCHEMA || typeof value.phase !== 'string' || !Object.hasOwn(filenames, value.phase) ||
      !['SAVED','UNAVAILABLE'].includes(value.status)) return null;
  const result = { schema:SCHEMA, status:value.status, phase:value.phase,
    errorClass:classes.has(value.errorClass) ? value.errorClass : 'Error' };
  if (value.status === 'SAVED') {
    if (value.file !== filenames[value.phase] || !Number.isSafeInteger(value.bytes) ||
        value.bytes <= 0 || typeof value.sha256 !== 'string' || !/^[a-f0-9]{64}$/.test(value.sha256))
      return null;
    Object.assign(result, { file:value.file, bytes:value.bytes, sha256:value.sha256 });
  } else result.writeErrorCode = safeCode(value.writeErrorCode, 'INBOX_DIAGNOSTIC_WRITE_FAILED');
  return Object.freeze(result);
}

/**
 * Preserve the actual failure without replacing its original public error code.
 * The source hashes describe files observed after failure, not a new execution.
 */
export async function retainInboxDiagnostic(problem, {
  phase, runtimeDirectory, inputFile, resultFile, command = null, workerFile,
}) {
  const reference = { schema:SCHEMA, phase, errorClass:errorClass(problem) };
  try {
    need(Object.hasOwn(filenames, phase), 'INBOX_DIAGNOSTIC_PHASE_INVALID');
    inputFile = absolute(inputFile);
    resultFile = absolute(resultFile);
    const directory = await privateDirectory(dirname(resultFile), { create:false });
    need(dirname(inputFile) === directory && inputFile !== resultFile,
      'INBOX_DIAGNOSTIC_DIRECTORY_MISMATCH');
    runtimeDirectory = absolute(runtimeDirectory);
    const sourceFiles = [
      absolute(workerFile), inputFile,
      join(runtimeDirectory, 'queue.mjs'), join(runtimeDirectory, 'config.mjs'),
      absolute(join(runtimeDirectory, '../sf81-buyer-operator-bridge/bridge.mjs')),
      absolute(join(runtimeDirectory, '../sf86-rpc-transfer-reconcile/networks.json')),
    ];
    const record = {
      schema:SCHEMA, phase, observedAt:new Date().toISOString(),
      command:typeof command === 'string' ? command : null,
      runtimeDirectory, inputFile, resultFile,
      error:privateErrorGraph(problem),
      sourceObservation:{ phase:'AFTER_FAILURE',
        files:await Promise.all([...new Set(sourceFiles)].map(observedSource)) },
    };
    const bytes = jsonBytes(record), file = filenames[phase];
    await writeBytes(join(directory, file), bytes, { exclusive:true });
    return normalizeInboxDiagnostic({ ...reference, status:'SAVED',
      file, bytes:bytes.length, sha256:digest(bytes) });
  } catch (writeProblem) {
    return normalizeInboxDiagnostic({ ...reference, status:'UNAVAILABLE',
      writeErrorCode:safeCode(writeProblem?.code, 'INBOX_DIAGNOSTIC_WRITE_FAILED') });
  }
}

// MIT — Node customer workflow on the original durable, exact-intent inbox.
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { BuyerResult, VerifiedFile } from './result.mjs';
import { absolute, intent, digest, object, need, BuyerError, safeCode, now,
  readJson, writeJson, syncDirectory } from './store.mjs';

import { normalizeInboxDiagnostic } from './inbox-diagnostics.mjs';

const SCHEMA = 'stellar-forge.node-buyer-inbox-command.v1';
const INBOX = 'stellar-forge.sf88.buyer-inbox.v1';
const worker = fileURLToPath(new URL('./inbox-worker.mjs', import.meta.url));
const freeze = value => {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    for (const child of Object.values(value)) freeze(child);
    Object.freeze(value);
  }
  return value;
};

export class InboxResult {
  constructor(run, commandDirectory) {
    this.native = freeze(structuredClone(run.output?.native ?? null));
    this.process = Object.freeze({ exitCode:run.exitCode ?? null,
      exitSignal:run.exitSignal ?? null, errorCode:run.errorCode ?? run.output?.error ?? null });
    this.commandDirectory = commandDirectory;
    this.diagnostic = normalizeInboxDiagnostic(run.output?.diagnostic ?? run.diagnostic);
    Object.freeze(this);
  }
}

export class InboxError extends BuyerError {
  constructor(code, result, details = {}) {
    const diagnostic = result.diagnostic;
    super(code, { result, ...details, ...(diagnostic ? { diagnostic,
      ...(diagnostic.status === 'SAVED' && result.commandDirectory
        ? { diagnosticPath:join(result.commandDirectory, diagnostic.file) } : {}) } : {}) });
    this.name = 'InboxError';
  }
  toJSON() {
    return { ...super.toJSON(), ...(this.diagnostic ? { diagnostic:this.diagnostic } : {}) };
  }
}

async function command(buyer, commandName, input, {signal} = {}) {
  need(signal === undefined || signal instanceof AbortSignal, 'INVALID_ABORT_SIGNAL');
  need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
  await buyer.ready();
  const directory = await mkdtemp(join(buyer.stateDirectory, '.inbox-command-'));
  const inputFile = join(directory, 'request.json'), resultFile = join(directory, 'native.json');
  let run;
  try {
    await writeJson(inputFile, { schema:SCHEMA, command:commandName, ...input }, { exclusive:true });
    await syncDirectory(buyer.stateDirectory);
    run = await buyer.runtime.run([buyer.runtime.directory, inputFile, resultFile], {
      directory, signal, entryFile:worker, resultFile, resultLimit:buyer.inboxReportLimit,
    });
    const output = run.output;
    need(object(output) && output.schema === SCHEMA && output.command === commandName &&
      output.root === (input.root ?? null), 'INBOX_NATIVE_RESULT_UNAVAILABLE');
    if (output.error) throw new BuyerError(output.error);
    need(object(output.native), 'INBOX_NATIVE_RESULT_INVALID');
    if (input.intentId) need(output.native.schema === INBOX &&
      output.native.operation?.intentId === input.intentId, 'INBOX_NATIVE_INTENT_MISMATCH');
    if (run.errorCode || run.exitSignal || ![0,2].includes(run.exitCode))
      throw new BuyerError(run.errorCode ?? 'INBOX_NATIVE_COMMAND_FAILED');
    let retained = null;
    try { await rm(directory, { recursive:true, force:true }); }
    catch { retained = directory; }
    // Cleanup cannot turn a known native completion into an uncertain action.
    const result = new InboxResult(run, retained);
    return { result, responseFile:output.responseFile };
  } catch (problem) {
    const result = new InboxResult(run ?? { errorCode:safeCode(problem?.code, 'INBOX_NATIVE_COMMAND_FAILED') }, directory);
    throw new InboxError(safeCode(problem?.code, 'INBOX_NATIVE_COMMAND_FAILED'), result,
      { commandDirectory:directory, ...(input.intentId ? {intentId:input.intentId} : {}),
        ...(input.root ? {inboxDirectory:input.root} : {}) });
  }
}

function lostOutputSelection({approvedRequestFile,approvedRequest,expectedRequestSha256,expectedAttemptId,expectedConfigSha256}) {
  need((approvedRequestFile !== undefined) !== (approvedRequest !== undefined),
    'LOST_OUTPUT_ONE_APPROVED_REQUEST_SOURCE_REQUIRED');
  if (approvedRequest !== undefined) need(object(approvedRequest), 'LOST_OUTPUT_APPROVED_REQUEST_REQUIRED');
  const input = approvedRequestFile === undefined
    ? {approvedRequest:structuredClone(approvedRequest)} : {approvedRequestFile:absolute(approvedRequestFile)};
  for (const [name,value] of Object.entries({expectedRequestSha256,expectedAttemptId,expectedConfigSha256})) {
    if (value === undefined) continue;
    need(typeof value === 'string' && (name === 'expectedAttemptId'
      ? /^[A-Za-z0-9._:-]{1,128}$/.test(value) : /^[a-f0-9]{64}$/.test(value)),
      'LOST_OUTPUT_SELECTED_ATTEMPT_INVALID');
    input[name] = value;
  }
  return input;
}

/** Inspect the complete private merchant packet with the installed native reader. */
export async function inspectOperationHandoff(buyer, file, {accept, signal} = {}) {
  if (accept !== undefined) need(Number.isSafeInteger(accept) && accept >= 0, 'EXPLICIT_SELECTION_INDEX_REQUIRED');
  const {result} = await command(buyer, 'inspect-packet', {file:absolute(file),
    ...(accept === undefined ? {} : {accept})}, {signal});
